				/**
				* 🔹 Utility method to remove nulls safely
				*/
				private <T> List<T> safeList(List<T> list) {
				if (list == null) return new ArrayList<>();
				return list.stream().filter(Objects::nonNull).collect(Collectors.toList());
				}


