public List<Object[]> getM_SRWA_12BResub() {
    List<Object[]> resubList = new ArrayList<>();
    try {
        List<M_SRWA_12B_Resub_Summary_Entity1> latestArchivalList = getResubSummaryAllVersions1();

        if (latestArchivalList != null && !latestArchivalList.isEmpty()) {
            for (M_SRWA_12B_Resub_Summary_Entity1 entity : latestArchivalList) {
                resubList.add(new Object[] {
                        entity.getReportDate(),
                        entity.getReportVersion(),
                        entity.getReportResubDate()
                });
            }
            System.out.println("Fetched " + resubList.size() + " record(s)");
        } else {
            System.out.println("No archival data found.");
        }

    } catch (Exception e) {
        System.err.println("Error fetching M_SRWA_12B Resub data: " + e.getMessage());
        e.printStackTrace();
    }
    return resubList;
}
